const i = $.input;
const params = {};
const page = Math.max(1, Math.min(500, i.page || 1));
const perPage = Math.max(1, Math.min(100, i.perPage || 25));
params.page = String(page);
params.per_page = String(perPage);

if (i.personTitles && i.personTitles.length) {
  i.personTitles.forEach((t, idx) => { params['person_titles[' + idx + ']'] = t; });
}
if (i.personSeniorities && i.personSeniorities.length) {
  i.personSeniorities.forEach((s, idx) => { params['person_seniorities[' + idx + ']'] = s; });
}
if (i.personLocations && i.personLocations.length) {
  i.personLocations.forEach((l, idx) => { params['person_locations[' + idx + ']'] = l; });
}
if (i.organizationDomains && i.organizationDomains.length) {
  i.organizationDomains.forEach((d, idx) => { params['q_organization_domains_list[' + idx + ']'] = d; });
}
if (i.organizationLocations && i.organizationLocations.length) {
  i.organizationLocations.forEach((l, idx) => { params['organization_locations[' + idx + ']'] = l; });
}
if (i.employeeRanges && i.employeeRanges.length) {
  i.employeeRanges.forEach((r, idx) => { params['organization_num_employees_ranges[' + idx + ']'] = r; });
}
if (i.technologies && i.technologies.length) {
  i.technologies.forEach((t, idx) => { params['currently_using_any_of_technology_uids[' + idx + ']'] = t; });
}
if (i.keywords) params.q_keywords = i.keywords;

return { params, page, perPage };

const resp = $.steps.searchPeople.response || {};
const people = (resp.people || []).map(p => ({
  id: p.id,
  firstName: p.first_name,
  lastName: p.last_name_obfuscated || '',
  title: p.title || '',
  hasEmail: p.has_email || false,
  hasPhone: p.has_direct_phone === 'Yes',
  organization: p.organization ? p.organization.name : '',
  location: [p.has_city && 'city', p.has_state && 'state', p.has_country && 'country'].filter(Boolean).length > 0
}));

const totalEntries = resp.total_entries || 0;
const page = $.steps.buildParams.output.page;
const perPage = $.steps.buildParams.output.perPage;

return {
  people,
  totalEntries,
  page,
  perPage,
  totalPages: Math.ceil(totalEntries / perPage),
  count: people.length,
  summary: totalEntries > 0
    ? `Found ${totalEntries.toLocaleString()} people (showing page ${page}, ${people.length} results)`
    : 'No people matched your search criteria'
};
